function validate([n, k, stayScore, travelScore]) {
  if (n < 1 || n > 200) return 'n is between 1 and 200.';
  if (k < 1 || k > 200) return 'k is between 1 and 200.';
  if (stayScore.length !== k || stayScore.some(row => row.length !== n)) return 'stayScore needs k rows of n scores.';
  if (travelScore.length !== n || travelScore.some(row => row.length !== n)) return 'travelScore must have n rows of n scores.';
  if (stayScore.some(row => row.some(v => v < 1 || v > 100))) return 'Each stayScore value is between 1 and 100.';
  if (travelScore.some(row => row.some(v => v < 0 || v > 100))) return 'Each travelScore value is between 0 and 100.';
  if (travelScore.some((row, i) => row[i] !== 0)) return 'travelScore[i][i] must be 0.';
  return null;
}

