function maxScore(n, k, stayScore, travelScore) {
  const dp = Array.from({ length: k + 1 }, () => new Array(n).fill(0));

  for (let day = 0; day < k; day++) {
    for (let dest = 0; dest < n; dest++) {
      let most = dp[day][dest] + stayScore[day][dest];
      for (let curr = 0; curr < n; curr++) {
        if (curr !== dest) {
          most = Math.max(most, dp[day][curr] + travelScore[curr][dest]);
        }
      }
      dp[day + 1][dest] = most;
    }
  }
  return Math.max(...dp[k]);
}

