function maxScore(n, k, stayScore, travelScore) {
  // Try every whole itinerary: each start city, then every choice of next city on every day.
  const explore = (day, city) => {
    if (day === k) return 0;
    let best = -Infinity;
    for (let next = 0; next < n; next++) {
      const points = next === city ? stayScore[day][city] : travelScore[city][next];
      best = Math.max(best, points + explore(day + 1, next));
    }
    return best;
  };
  let answer = -Infinity;
  for (let start = 0; start < n; start++) answer = Math.max(answer, explore(0, start));
  return answer;
}

