function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  let n, k;
  if (size === 'large') {
    // Keep every value of the case, rows included, under the app's 20,000-value limit.
    n = int(90, 100);
    k = Math.min(100, Math.floor((19990 - n - n * n) / (n + 1)));
  } else {
    n = int(1, 5);
    k = int(1, 5);
  }
  // Small score ranges create ties between staying and moving.
  const top = size === 'large' || rand() < 0.5 ? 100 : int(1, 6);
  const stayScore = Array.from({ length: k }, () => Array.from({ length: n }, () => int(1, top)));
  const travelScore = Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => (i === j ? 0 : int(0, top))));
  return [n, k, stayScore, travelScore];
}
